package pipeline

import (
	"sync"
)

type Buffer struct {
	Data []byte
}

func (b *Buffer) Reset() {
	b.Data = b.Data[:0]
}

type BufferPool struct {
	pool sync.Pool
}

func NewBufferPool(capacity int) *BufferPool {
	return &BufferPool{
		pool: sync.Pool{
			New: func() any {
				return &Buffer{
					Data: make([]byte, 0, capacity),
				}
			},
		},
	}
}

func (p *BufferPool) Get() *Buffer {
	buf := p.pool.Get().(*Buffer)
	buf.Reset()
	return buf
}

func (p *BufferPool) Put(buf *Buffer) {
	if buf != nil {
		p.pool.Put(buf)
	}
}

