package pipeline

import (
	"encoding/binary"
	"errors"
)

type Event struct {
	Timestamp int64
	SensorID  uint32
	Value     float64
}

type FastParser struct{}

func NewFastParser() *FastParser {
	return &FastParser{}
}

func (p *FastParser) ParseEvent(data []byte, out *Event) error {
	if len(data) < 20 {
		return errors.New("insufficient packet length")
	}
	out.Timestamp = int64(binary.BigEndian.Uint64(data[0:8]))
	out.SensorID = binary.BigEndian.Uint32(data[8:12])
	out.Value = float64(binary.BigEndian.Uint64(data[12:20]))
	return nil
}

fixtures.pipeline/stream.go:
package pipeline

import (
	"context"
	"io"
)

type StreamProcessor struct {
	pool   *BufferPool
	parser *FastParser
}

func NewStreamProcessor(bufCap int) *StreamProcessor {
	return &StreamProcessor{
		pool:   NewBufferPool(bufCap),
		parser: NewFastParser(),
	}
}

func (s *StreamProcessor) ProcessStream(ctx context.Context, reader io.Reader, handler func(Event)) error {
	buf := s.pool.Get()
	defer s.pool.Put(buf)

	var event Event
	tempBuf := make([]byte, 20)
	for {
		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
		}
		_, err := io.ReadFull(reader, tempBuf)
		if err == io.EOF || err == io.ErrUnexpectedEOF {
			break
		}
		if err != nil {
			return err
		}
		if err := s.parser.ParseEvent(tempBuf, &event); err != nil {
			continue
		}
		handler(event)
	}
	return nil
}

fixtures.pipeline/profiler.go:
package pipeline

import (
	"bytes"
	"runtime"
	"runtime/pprof"
)

type ProfileSnapshot struct {
	AllocBytes uint64
	TotalAlloc uint64
	NumGC      uint32
}

type Profiler struct{}

func NewProfiler() *Profiler {
	return &Profiler{}
}

func (p *Profiler) CaptureHeapProfile() (*ProfileSnapshot, error) {
	runtime.GC()
	var m runtime.MemStats
	runtime.ReadMemStats(&m)
	var buf bytes.Buffer
	if err := pprof.WriteHeapProfile(&buf); err != nil {
		return nil, err
	}
	return &ProfileSnapshot{
		AllocBytes: m.Alloc,
		TotalAlloc: m.TotalAlloc,
		NumGC:      m.NumGC,
	},
	nil
}
